/** One pre-seeded row in the "Add account" form for a known auth shape. */
export interface BYOKCredentialField {
  name: string;
  /** Render as a hidden password input. Defaults to true. */
  secret?: boolean;
  /** Hint text for the value input (e.g. a default port). */
  placeholder?: string;
}

// Pre-configured credential field shapes for providers whose auth is NOT a
// single API key — databases (host/port/user/password), AWS-style key pairs,
// and SaaS that need a domain or account id alongside the token. The
// "Add account" modal seeds these rows so users don't have to guess field
// names (e.g. Postgres never takes an "api_key"). Only providers whose shape
// we're confident about are listed here; everything else falls back to a
