function inflateStub([id, name]: readonly [string, string, number]): CredentialSpec {
  return {
    credential_id: id,
    credential_name: name,
    env_var: `${id.toUpperCase()}_API_KEY`,
    description: BYOK_DESCRIPTIONS[id] ?? "",
    help_url: "",
    api_key_instructions: "",
    tools: [],
    aden_supported: false,
    direct_api_key_supported: true,
    credential_key: "api_key",
    credential_group: "",
    available: false,
    accounts: [],
  };
}

export const BYOK_CATALOG_SPECS: CredentialSpec[] = [
  ...FULL_SPECS,
  ...STUB_BYOK.map(inflateStub),
];

export const BYOK_CATALOG_IDS: Set<string> = new Set(
  BYOK_CATALOG_SPECS.map((s) => s.credential_id),
);

// GTM-relevancy score (0-100) per credential id — drives the default
// "By Popularity" ordering of the API Keys grid on the credentials page.
export const BYOK_POPULARITY: Record<string, number> = Object.fromEntries(
  STUB_BYOK.map(([id, , score]) => [id, score]),
);
